	/** A scripted hedge support producing {@code backupValue} after {@code delayMillis} on the pool thread. */
	private static LmdbNativeHedgeSupport<String> scriptedSupport(String backupValue, long delayMillis,
			CountDownLatch produced, AtomicInteger discards) {
		return new LmdbNativeHedgeSupport<>() {

			@Override
			public LmdbNativeHedgeSupport.ShadowContext openShadowContext() {
				return new LmdbNativeHedgeSupport.ShadowContext(
						mock(NativeLmdbQuerySource.ParallelSource.class), row(layout(1)));
			}

			@Override
			public String produceBackup(LmdbNativeHedgeSupport.ShadowContext context, String pinnedTag,
					LmdbNativeCostObservation observation) throws Exception {
				if (delayMillis > 0L) {
					Thread.sleep(delayMillis);
				}
				int tick = 0;
				LmdbNativeProbeDeadline.poll(tick); // honor a trip that arrived while sleeping
				if (produced != null) {
					produced.countDown();
				}
				return backupValue;
			}

			@Override
			public String adopt(String result) {
				return result;
			}

			@Override
			public void discard(String result) {
				if (discards != null) {
					discards.incrementAndGet();
				}
			}

			@Override
			public boolean supportsTag(String pinnedTag) {
				return LmdbNativeAttemptMetrics.PATH_BATCH.equals(pinnedTag);
			}
		};
	}

