	@Test
	void aConfidentlyMispricedWinnerIsRescuedByTheParallelRunnerUp() throws Exception {
		AtomicInteger winnerOpens = new AtomicInteger();
		AtomicInteger backupOpens = new AtomicInteger();
		LmdbNativeStrategyProposal<String> winner = spinningWinner(winnerOpens);
		Fixture fixture = guardFixture(winner, trustedBackupProposal(new AtomicInteger()), GUARDED_WINNER_NANOS,
				GUARD_BACKUP_NANOS);
		LmdbNativeCostEstimate winnerEstimate = winner.adaptiveEstimate(-1D);

		long startedNanos = System.nanoTime();
		String result = dispatch(fixture, spinningWinner(winnerOpens), trustedBackupProposal(backupOpens),
				guardSupport("rescued", true));
		long elapsedNanos = System.nanoTime() - startedNanos;

		assertEquals("rescued", result, "the parallel runner-up's result is adopted — no unbounded stall");
		assertEquals(1, winnerOpens.get(), "the mispriced winner ran exactly once");
		assertTrue(elapsedNanos < TimeUnit.SECONDS.toNanos(5),
				"the rescue must land in trigger + backup time, not an unbounded stall (took " + elapsedNanos + ")");
		LmdbNativeRegimeKey regime = fixture.model().currentRegime();
		assertEquals(LmdbNativeProbeScheduler.State.QUARANTINED,
				fixture.store().probeScheduler().state(winnerEstimate.variantKey(), regime, 0L),
				"a winner that lost its guarded race is quarantined (price untrusted)");
		LmdbNativeCostPosteriorStore.ExactKey key = LmdbNativeCostPosteriorStore.ExactKey.of(regime,
				LmdbNativeCostPosteriorStore.Lane.RESIDUAL, winnerEstimate.variantKey());
		LmdbNativeCostPosteriorStore.Reading reading = fixture.store()
				.posteriors()
				.read(key, 0L, fixture.store().nowMillis());
		assertEquals(1, reading.exact().censoredCount, "the displaced winner is right-censored, never completed");
	}

	@Test
	void aWinnerFinishingBeforeTheTriggerCommitsWithOnlyTimerOverhead() throws Exception {
		AtomicInteger backupOpens = new AtomicInteger();
		LmdbNativeStrategyProposal<String> fastWinnerTemplate = new LmdbNativeStrategyProposal<>(() -> "winner",
				LmdbNativeWork.exact(1_000D), LmdbNativeAttemptMetrics.PATH_BATCH, () -> {
				});
		Fixture fixture = guardFixture(fastWinnerTemplate, trustedBackupProposal(new AtomicInteger()),
				GUARDED_WINNER_NANOS, GUARD_BACKUP_NANOS);

		String result = dispatch(fixture,
				new LmdbNativeStrategyProposal<>(() -> "winner", LmdbNativeWork.exact(1_000D),
						LmdbNativeAttemptMetrics.PATH_BATCH, () -> {
						}),
				trustedBackupProposal(backupOpens), guardSupport("rescued", true));

		assertEquals("winner", result, "a healthy winner publishes; the armed guard never fires");
		assertEquals(0, backupOpens.get(), "the runner-up proposal itself was never opened");
		// the idle backup task must exit and release its permit once the race commits the primary
		long waitUntil = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (!LmdbNativeHedgePermits.spareCapacity(LmdbNativeHedgeConfig.defaults())
				&& System.nanoTime() < waitUntil) {
			Thread.sleep(5L);
		}
		assertTrue(LmdbNativeHedgePermits.spareCapacity(LmdbNativeHedgeConfig.defaults()),
				"the unfired guard released its permit");
	}

	@Test
	void theDegradedGuardCensorsAtTheTriggerAndFallsBackSerially() throws Exception {
		AtomicInteger winnerOpens = new AtomicInteger();
		AtomicInteger backupOpens = new AtomicInteger();
		LmdbNativeStrategyProposal<String> winner = spinningWinner(winnerOpens);
		Fixture fixture = guardFixture(winner, trustedBackupProposal(new AtomicInteger()), GUARDED_WINNER_NANOS,
				GUARD_BACKUP_NANOS);

		String result = dispatch(fixture, spinningWinner(winnerOpens), trustedBackupProposal(backupOpens),
				guardSupport("rescued", false));

		assertEquals("serial-runner-up", result,
				"no shadow context: the degraded guard censors the winner at its trigger and re-ranks serially");
		assertEquals(1, winnerOpens.get());
		assertEquals(1, backupOpens.get(), "the runner-up opened serially after the censor");
	}

	private static NativeSlotLayout layout(int slots) {
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		for (int slot = 0; slot < slots; slot++) {
			names.put("v" + slot, slot);
		}
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(new ArrayList<>(names.keySet()));
		return layout;
	}

	private static RowState row(NativeSlotLayout layout) {
		RowState row = new RowState(null, layout, EmptyBindingSet.getInstance());
		java.util.Arrays.fill(row.slots, NativeLmdbQuerySource.UNKNOWN_ID);
		row.recomputeBoundMask();
		return row;
	}
